begin; create extension if not exists pgcrypto; create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique not null check (username ~ '^[A-Za-z0-9_]{3,24}$'), role text not null default 'user' check (role in ('user','admin')), balance numeric(14,2) not null default 0 check (balance >= 0), reserved_balance numeric(14,2) not null default 0 check (reserved_balance >= 0 and reserved_balance <= balance), disabled boolean not null default false, created_at timestamptz not null default now()); create table if not exists public.jobs (id uuid primary key default gen_random_uuid(), title text not null, description text not null default '', reward numeric(14,2) not null default 0 check (reward >= 0), status text not null default 'active' check (status in ('draft','active','paused','closed')), created_at timestamptz not null default now()); create table if not exists public.submissions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, job_id uuid not null references public.jobs(id) on delete restrict, note text not null default '', proof_url text not null default '', status text not null default 'pending' check (status in ('pending','approved','rejected','paid','completed')), review_note text, reviewed_at timestamptz, created_at timestamptz not null default now(), unique(user_id,job_id)); create table if not exists public.withdrawals (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, amount numeric(14,2) not null check(amount > 0), method text not null, destination text not null, status text not null default 'pending' check(status in ('pending','approved','rejected','paid','completed')), review_note text, reviewed_at timestamptz, created_at timestamptz not null default now()); create table if not exists public.robux_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, method text not null check(method in ('gamepass','username')), amount integer not null check(amount > 0), username text not null, gamepass_url text not null default '', rate numeric(14,2) not null check(rate > 0), cost numeric(14,2) not null check(cost > 0), status text not null default 'pending' check(status in ('pending','approved','rejected','paid','completed')), review_note text, reviewed_at timestamptz, created_at timestamptz not null default now()); create table if not exists public.settings (key text primary key, value jsonb not null default 'null'::jsonb); create table if not exists public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles(id) on delete set null, action text not null, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()); create table if not exists public.wallet_transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, amount numeric(14,2) not null check(amount <> 0), kind text not null, description text not null default '', reference_id uuid, created_at timestamptz not null default now()); create index if not exists jobs_status_created_idx on public.jobs(status,created_at desc); create index if not exists submissions_user_created_idx on public.submissions(user_id,created_at desc); create index if not exists withdrawals_user_created_idx on public.withdrawals(user_id,created_at desc); create index if not exists robux_requests_user_created_idx on public.robux_requests(user_id,created_at desc); create index if not exists audit_logs_created_idx on public.audit_logs(created_at desc); alter table public.profiles enable row level security; alter table public.jobs enable row level security; alter table public.submissions enable row level security; alter table public.withdrawals enable row level security; alter table public.robux_requests enable row level security; alter table public.settings enable row level security; alter table public.audit_logs enable row level security; alter table public.wallet_transactions enable row level security; revoke all on public.profiles,public.jobs,public.submissions,public.withdrawals,public.robux_requests,public.settings,public.audit_logs,public.wallet_transactions from anon,authenticated; grant usage on schema public to service_role; grant all on public.profiles,public.jobs,public.submissions,public.withdrawals,public.robux_requests,public.settings,public.audit_logs,public.wallet_transactions to service_role; create or replace function public.create_withdrawal(p_user_id uuid,p_amount numeric,p_method text,p_destination text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare p public.profiles%rowtype; w public.withdrawals%rowtype; begin if p_amount<=0 or length(trim(coalesce(p_method,'')))=0 or length(trim(coalesce(p_destination,'')))=0 then raise exception 'Input penarikan tidak valid'; end if; select * into p from public.profiles where id=p_user_id for update; if not found or p.disabled then raise exception 'Akun tidak tersedia'; end if; if p.balance-p.reserved_balance<p_amount then raise exception 'Saldo tidak mencukupi'; end if; update public.profiles set balance=balance-p_amount where id=p_user_id; insert into public.withdrawals(user_id,amount,method,destination,status) values(p_user_id,p_amount,left(p_method,50),left(p_destination,200),'pending') returning * into w; insert into public.wallet_transactions(user_id,amount,kind,description,reference_id) values(p_user_id,-p_amount,'withdrawal','Pengajuan penarikan',w.id); return to_jsonb(w); end; $$; create or replace function public.create_robux_request(p_user_id uuid,p_method text,p_robux integer,p_username text,p_gamepass_url text,p_rate numeric,p_cost numeric) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare p public.profiles%rowtype; r public.robux_requests%rowtype; begin if p_method not in ('gamepass','username') or p_robux<=0 or p_rate<=0 or p_cost<>p_robux*p_rate or length(trim(coalesce(p_username,'')))=0 or (p_method='gamepass' and coalesce(p_gamepass_url,'') not like 'https://www.roblox.com/%') then raise exception 'Permintaan Robux tidak valid'; end if; select * into p from public.profiles where id=p_user_id for update; if not found or p.disabled then raise exception 'Akun tidak tersedia'; end if; if p.balance-p.reserved_balance<p_cost then raise exception 'Saldo tidak mencukupi'; end if; update public.profiles set reserved_balance=reserved_balance+p_cost where id=p_user_id; insert into public.robux_requests(user_id,method,amount,username,gamepass_url,rate,cost,status) values(p_user_id,p_method,p_robux,left(p_username,100),left(coalesce(p_gamepass_url,''),500),p_rate,p_cost,'pending') returning * into r; return to_jsonb(r); end; $$; create or replace function public.admin_adjust_balance(p_user_id uuid,p_amount numeric,p_reason text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare p public.profiles%rowtype; begin if p_amount=0 then raise exception 'Nominal tidak valid'; end if; select * into p from public.profiles where id=p_user_id for update; if not found then raise exception 'Akun tidak ditemukan'; end if; if p.balance+p_amount<p.reserved_balance then raise exception 'Saldo tidak boleh kurang dari saldo tertahan'; end if; update public.profiles set balance=balance+p_amount where id=p_user_id returning * into p; insert into public.wallet_transactions(user_id,amount,kind,description) values(p_user_id,p_amount,'adjustment',left(coalesce(p_reason,'Admin adjustment'),200)); return jsonb_build_object('id',p.id,'balance',p.balance,'reserved_balance',p.reserved_balance); end; $$; revoke all on function public.create_withdrawal(uuid,numeric,text,text) from public,anon,authenticated; revoke all on function public.create_robux_request(uuid,text,integer,text,text,numeric,numeric) from public,anon,authenticated; revoke all on function public.admin_adjust_balance(uuid,numeric,text) from public,anon,authenticated; grant execute on function public.create_withdrawal(uuid,numeric,text,text) to service_role; grant execute on function public.create_robux_request(uuid,text,integer,text,text,numeric,numeric) to service_role; grant execute on function public.admin_adjust_balance(uuid,numeric,text) to service_role; commit;